WITH matched_keys AS (SELECT id, city FROM suppliers INTERSECT ALL SELECT id, city FROM suppliers WHERE supplier_name LIKE 'Glo%'), kept_rows AS (SELECT s.* FROM suppliers s INNER JOIN matched_keys k ON s.id = k.id AND s.city = k.city), cleaned AS (SELECT *, UPPER(country) AS country_upper, COALESCE(city, 'UNKNOWN') AS resolved_city FROM kept_rows WHERE city IS NOT NULL AND supplier_name NOT LIKE '%Sup%'), metrics AS (SELECT *, DENSE_RANK() OVER w_grp AS rating_dense_rank, RANK() OVER (PARTITION BY country ORDER BY rating DESC NULLS FIRST) AS rating_rank, ROUND(rating / SUM(rating) OVER (PARTITION BY country), 4) AS rating_share FROM cleaned WINDOW w_grp AS (ORDER BY rating DESC NULLS LAST)), not_flagged AS (SELECT s.* FROM metrics s WHERE NOT EXISTS (SELECT 1 FROM products x WHERE x.supplier_id = s.id AND x.price > 560)), base AS (SELECT *, LEAST(rating_rank, rating_share) AS least_rating_rank_rating_share FROM not_flagged WHERE country IN ('DE', 'JP')), stats AS (SELECT CASE WHEN least_rating_rank_rating_share >= 78 THEN 'LARGE' ELSE 'SMALL' END AS least_rating_rank_rating_share_tier, SORT_ARRAY(COLLECT_SET(city)) AS city_list, SORT_ARRAY(COLLECT_SET(country)) AS country_list, ROUND(SUM(rating_share) / NULLIF(COUNT(CASE WHEN country = 'US' THEN 1 END), 0), 2) AS rating_share_per_us, SIZE(COLLECT_SET(country)) AS num_countries FROM base GROUP BY CASE WHEN least_rating_rank_rating_share >= 78 THEN 'LARGE' ELSE 'SMALL' END) SELECT least_rating_rank_rating_share_tier, city_list, rating_share_per_us, num_countries FROM stats
